def solve_knight_tour():
    N = 8
    fixed = {
        0: 0,
        2: 27,
        3: 21,
        10: 16,
        11: 1,
        19: 24,
        21: 3,
        27: 51,
        38: 38,
        50: 43,
        51: 60,
        59: 53,
        61: 42
    }

    moves = [
        (1, 2), (1, -2), (-1, 2), (-1, -2),
        (2, 1), (2, -1), (-2, 1), (-2, -1)
    ]

    def get_coords(cell):
        return cell // N, cell % N

    def get_cell(r, c):
        return r * N + c

    def get_possible_moves(cell):
        r, c = get_coords(cell)
        possible = []
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                possible.append(get_cell(nr, nc))
        return possible

    path = [None] * 64
    visited = [False] * 64

    for step, cell in fixed.items():
        path[step] = cell
        visited[cell] = True

    # Warnsdorff's rule heuristic
    def count_degree(cell, current_visited):
        count = 0
        for next_cell in get_possible_moves(cell):
            if not current_visited[next_cell]:
                count += 1
        return count

    def solve(step):
        if step == 64:
            return True

        if path[step] is not None:
            # Already fixed, just check if it's a valid move from path[step-1]
            if step > 0:
                r1, c1 = get_coords(path[step-1])
                r2, c2 = get_coords(path[step])
                if abs(r1 - r2) * abs(c1 - c2) != 2:
                    return False
            return solve(step + 1)

        # Try all possible moves from path[step-1]
        prev_cell = path[step-1]

        # Get possible moves and sort by Warnsdorff's rule
        possible_moves = []
        for next_cell in get_possible_moves(prev_cell):
            if not visited[next_cell]:
                # Check if next_cell is already assigned to some other step
                is_fixed_elsewhere = False
                for s, c in fixed.items():
                    if c == next_cell and s != step:
                        is_fixed_elsewhere = True
                        break
                if not is_fixed_elsewhere:
                    possible_moves.append(next_cell)

        # Sort by degree
        possible_moves.sort(key=lambda c: count_degree(c, visited))

        for next_cell in possible_moves:
            path[step] = next_cell
            visited[next_cell] = True
            if solve(step + 1):
                return True
            visited[next_cell] = False
            path[step] = None
        return False

    if solve(0):
        return path
    else:
        return None

